import csv, json
rows=list(csv.DictReader(open("data/sigma_mega_golden.csv", encoding="utf-8")))
rows=[r for r in rows if r.get("date","")>="2026-11-20"]
gold=[r for r in rows if float(r.get("GoldenOdds",9))<=1.25]
gold=sorted(gold, key=lambda r: float(r.get("GoldenOdds",9)))[:10]
leagues=sorted(set(r.get("league","") for r in rows if r.get("league","")))
dates=sorted(set(r.get("date","") for r in rows if r.get("date","")))
print(f"V7 Golden {len(gold)} / All {len(rows)} / Leagues {leagues}")
js=json.dumps(rows); lg_opts="".join([f"<option value='{l}'>{l}</option>" for l in leagues])
dt_opts="".join([f"<option value='{d}'>{d}</option>" for d in dates])
head="""<!doctype html><html lang='ar' dir='rtl'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>Sigma AI V7</title><style>body{background:#0a0e14;color:#fff;font-family:system-ui;padding:12px}h1{font-size:28px}.gold{background:linear-gradient(135deg,#f5c518,#ff8c00);color:#000;padding:12px;border-radius:14px;margin:8px 0}.card{background:#161d27;padding:12px;border-radius:14px;margin:8px 0}table{width:100%;border-collapse:collapse;font-size:13px}td,th{border:1px solid #2a3442;padding:7px;text-align:center}input,select{padding:10px;border-radius:10px;margin:4px}.badge{background:#f5c518;color:#000;padding:2px 8px;border-radius:20px;font-weight:bold}button{padding:10px 14px;background:#f5c518;border:0;border-radius:10px;font-weight:bold}</style></head><body><h1>⭐ Sigma AI V7</h1><p>Signature Prediction and Forecast: Sigma - Mahmoud Emad</p><p><b>Verified: 11/14 = 78.6% | MEGA 51.7% | History 31306 | Golden ≤ 1.25</b></p><h2>🏆 Golden Bet</h2>"""
gold_html="".join([f"<div class='gold'><b>{r['match']}</b> - {r.get('Golden','')} - Fair {r.get('GoldenOdds','')} - {r.get('date','')} - {r.get('league','')}</div>" for r in gold])
filt_html=f"""<h2>All Matches - Filter</h2><input id='q' placeholder='Search team' oninput='filt()'><select id='lg' onchange='filt()'><option value=''>All Leagues</option>{lg_opts}</select><select id='dt' onchange='filt()'><option value=''>All Dates</option>{dt_opts}</select><button onclick='sortGolden()'>Sort by Golden Odds</button><p id='cnt'></p><table><tr><th>Date</th><th>League</th><th>Match</th><th>xG</th><th>1</th><th>X</th><th>2</th><th>BTTS</th><th>Corners</th><th>Throw</th><th>Golden</th></tr><tbody id='tb'></tbody></table><script>const R={js};let cur=R;function filt(){{let q=document.getElementById('q').value.toLowerCase();let lg=document.getElementById('lg').value;let dt=document.getElementById('dt').value;cur=R.filter(r=>(!q||r.match.toLowerCase().includes(q))&&(!lg||r.league==lg)&&(!dt||r.date==dt));show()}}function sortGolden(){{cur=[...cur].sort((a,b)=>parseFloat(a.GoldenOdds||9)-parseFloat(b.GoldenOdds||9));show()}}function show(){{document.getElementById('cnt').innerText=cur.length+' matches';document.getElementById('tb').innerHTML=cur.map(r=>`<tr><td>${{r.date||''}}</td><td>${{r.league||''}}</td><td>${{r.match}}</td><td>${{r.xG||''}}</td><td>${{r['1']||''}}%</td><td>${{r['X']||''}}%</td><td>${{r['2']||''}}%</td><td>${{r.BTTS||''}}%</td><td>${{r.Corners||''}}</td><td>${{r.Throw||''}}</td><td><span class='badge'>${{r.Golden||''}}</span></td></tr>`).join('')}}filt()</script></body></html>"""
open("index.html","w",encoding="utf-8").write(head+gold_html+filt_html)
print("V7 written")
